/* "Bose d'origine" engine: the stock Companion 5 signal graph (firmware D01.01.01) run module by module.
 *
 * src/bose/bose_graph_data.c is GENERATED by re/dsp/gen_bose_graph.py from the stock RAM image: one op per
 * stock module of the root container 0x100100C0, in the stock execution order, with the stock wire numbers
 * (buffer pool w0..w19, reused in place as stock) and the stock parameters, from the USB gain 0x100106C8 up to
 * the satellite band protection 0x10011450 (excluded):
 *   USB gain -> BADDATA selector (all-pass 0x100107A0 / LR4 0x100107DC, mixer 0x10010818) -> router -> AUX mix
 *   (x 1.8621) -> DC blocker 0x1001032C -> loudness (band-pass 0x100103C0, gains 0x100103FC / 0x10010430) ->
 *   realign x 3.334 (LFE x 6.668) -> spatial detection (HPF 0x10010A1C, L+R, L-R, meter 0x10010A98) and
 *   control 0x10027978 (bose_spatial.c) -> 2->6 matrix 0x10010B58 -> centre and surround mixers, mode mixers
 *   ('N') -> bass sum 0x10011430 -> speaker EQ 0x10010884 (8 sections, 4 sets) -> bass knob -> array networks
 *   0x10010D44 / 0x10011018 (delays 0..60 samples, cross-feed) -> output mixers 0x10011390..0x10011408.
 * The rest of the stock chain (band clippers, compressors, 320-sample look-ahead limiter on the satellites
 * only, bass clipper, final gain) is src/protect/, called by audio_out.c with the stock bass timing.
 * Signal levels: float +-1.0 = full scale on the inputs and at the DAC (as the stock graph).
 * Rate: 48 kHz only. */
#ifndef BOSE_GRAPH_H
#define BOSE_GRAPH_H

#include <stdint.h>
#include "oc.h"
#include "bose_graph_size.h"
#include "kern.h"

/* Op kinds. BG_UEQ (built-in programs only): user EQ bank op->par (eq.h EQ_BANK_*) on its nin wires, in place. */
enum { BG_GAIN, BG_MIX, BG_SUM, BG_ADD, BG_DELAY, BG_BIQUAD, BG_METER, BG_SPATIAL, BG_BASS, BG_COPY, BG_UEQ };
/* Hooks. BG_H_MTX (sum ops): weights from the run-time matrix ctl->mtx[op->par ...] (input routing variants). */
enum { BG_H_NONE, BG_H_USB, BG_H_LOUD_D, BG_H_LOUD_B, BG_H_BADDATA, BG_H_SPATIAL, BG_H_MTX };

typedef struct { uint8_t kind, nin, nout, hook; uint16_t io, par; } bg_op_t;   /* io: bg_io index */
typedef struct { uint16_t coef, z; uint8_t nsec, nsets, set[7]; } bg_bq_t;     /* per-channel set */
typedef struct { uint16_t off, d48; } bg_dl_t;

/* A program ("preset"): the stock graph (tables in the EEPROM graph data pages, coefficients in the image) or a
 * built-in one (src/bose/bose_progs.c). Sizes must fit the work RAM dimensioned for the stock graph (BG_N*). */
typedef struct {
    const bg_op_t *ops;
    const uint8_t *io;
    const bg_bq_t *bq;
    const bg_dl_t *dl;
    const float   *f;
    const uint8_t *out;                  /* 5 wires: inner L, inner R, outer L, outer R, bass */
    uint16_t nf;
    uint8_t  nops, nbq, ndl;
    uint8_t  flags;                      /* BGP_* */
    float    usb_level;                  /* scale of the USB inputs (AUX: 1) */
} bg_prog_t;
#define BGP_WRAP_EQ    1u                /* user EQ banks run around the program: global on inputs L / R, outputs after */
#define BGP_BASS_DELAY 2u                /* bass delayed like the satellites (look-ahead limiter alignment) */
extern const bg_prog_t bg_prog_bose, bg_prog_neutral;

extern const bg_op_t bg_ops[BG_NOPS];
extern const uint8_t bg_io[];
extern const bg_bq_t bg_bq[BG_NBQ];
extern const bg_dl_t bg_dl[BG_NDL];
extern const float   bg_f[BG_NF];
extern const uint8_t bg_out[5];          /* wires: inner L, inner R, outer L, outer R, bass */

/* Live values of the control-driven stock parameters, for one frame. */
typedef struct {
    const float *usb;      /* per-sample gain of the 6 USB channels (mute ramp), stock gain 0x100106C8 */
    const float *loud_d;   /* per-sample loudness direct gain (master volume included), 0x100103FC */
    const float *loud_b;   /* per-sample loudness band gain, 0x10010430 */
    float baddata;         /* 1 = BADDATA low-pass branch of the selector 0x10010758 */
    const float *mtx;      /* run-time weights of the BG_H_MTX sums (built-in programs) */
    unsigned ueq;          /* bit b set: user EQ bank b runs (BG_UEQ ops; headphones: global only, or none) */
} bg_ctl_t;


enum { BG_IN_L, BG_IN_R, BG_IN_C, BG_IN_LFE, BG_IN_LS, BG_IN_RS, BG_IN_AUX_L, BG_IN_AUX_R, BG_IN_COUNT };

void   bose_graph_select(const bg_prog_t *p); /* program to run (then as bose_graph_init) */
const bg_prog_t *bose_graph_program(void);
void   bose_graph_init(void);                 /* clears every state */
void   bose_graph_rate(void);                 /* coefficients, delays and smoother poles */
float *bose_graph_input(int ch);              /* BG_IN_*: fill FRAME_LEN samples before bose_graph_run() */
void   bose_graph_run(const bg_ctl_t *ctl);
float *bose_graph_output(int k);              /* 0..3 = inner L, inner R, outer L, outer R; 4 = bass */

/* --- bose_spatial.c: stock spatial control 0x10027978 (instance 0x10010AC0), once per frame --- */
typedef struct {
    float hold[6], fast[6], slow[6];          /* envelopes of L, R, L+R, L-R, max(L,R), max(S,D) */
    float cs;                                 /* smoothed coherence (2 s) */
    float width;                              /* width factor 0.5 .. 1.5 */
} bose_spatial_t;
extern bose_spatial_t g_spatial;
void bose_spatial_init(void);
/* pow4: block mean squares of HPF(L), HPF(R), sum, difference (meter 0x10010A98). g12: the 12 targets of
 * mixer 0x10010B58, pairs (gL, gR) for its outputs: direct L, direct R, array L, array R, third L, third R. */
void bose_spatial_block(const float pow4[4], float g12[12]);

#endif
